import{_ as a,o as e,c as n,aj as d}from"./chunks/framework.BdtAaXf2.js";const r="/assets/image-20251221113549057.C6n-fiTP.png",o="/assets/image-20251221113614582.DvvbJtal.png",i="/assets/image-20251221113836435.Clag8HLS.png",s="/assets/image-20251221113919425.B9LFBS2H.png",l="/assets/image-20251221114016973.Ckg-8K51.png",h="/assets/image-20251221114100208.u6sen69c.png",p="/assets/image-20251221114145829.BJAB9g_u.png",A=JSON.parse('{"title":"2025 万少的AI编程之旅","description":"","frontmatter":{},"headers":[],"relativePath":"AI人工智能/2025 万少的AI编程之旅/2025 万少的AI编程之旅.md","filePath":"AI人工智能/2025 万少的AI编程之旅/2025 万少的AI编程之旅.md","lastUpdated":1766289058000,"__rawMarkdown":"# 2025 万少的AI编程之旅\\n\\n## 前言\\n\\n距离新年2026就剩下不到两个星期的时间了，2025年的AI的发展可谓是百花齐放，我自己也是紧跟其中的发展，也在2025年的AI编程之旅中，学习了很多新的知识，也做出来一些自己的小作品。\\n\\n\\n\\n\\n\\n## 用到的AI编辑工具\\n\\n以下罗列下用到的AI编辑器。\\n\\n1. Cursor\\n2. claude code\\n3. Trae 海外版\\n4. Trae 国内版\\n5. CodeBuddy 海外版\\n6. CodeBuddy 国内版\\n7. Qoder\\n8. Antigravity\\n9. Iflow cli \\n\\n\\n\\n| 工具             | 类型       | 核心优势                 | 主要模型              | 价格                   |\\n| ---------------- | ---------- | ------------------------ | --------------------- | ---------------------- |\\n| Cursor           | IDE        | 界面友好，学习成本低     | Claude 系列           | 基础版免费             |\\n| Claude Code      | CLI        | 工程能力强，大型项目支持 | Opus/Sonnet 系列      | 订阅制 (Max $200 / 月) |\\n| Trae (海外)      | IDE/CLI    | 多模态，国际模型支持     | GPT-4o/Claude 系列    | 部分功能付费           |\\n| Trae (国内)      | IDE/CLI    | 全免费，国产模型         | 豆包 / DeepSeek 系列  | 永久免费               |\\n| CodeBuddy (海外) | 多形态     | 三模全开，企业级安全     | GPT-5/Claude-4/Gemini | 订阅制                 |\\n| CodeBuddy (国内) | 多形态     | 国产模型，安全可控       | 混元 / DeepSeek 系列  | 部分功能付费           |\\n| Qoder            | Agent 平台 | 智能调度，高效性能       | 多模型自动切换        | 部分功能付费           |\\n| Antigravity      | IDE        | 自主智能体，多 Agent     | Gemini/Claude 系列    | 个人版免费             |\\n| Iflow cli        | CLI        | 终端友好，分层配置       | 自研 + 第三方模型     | 永久免费               |\\n\\n## 伴随AI工具的发展，我做了的一些作品\\n\\n## 重构技术博客\\n\\n之前的技术博客是手动的使用 vitepress构建，自己配置了很久一些配置，现在想要增加什么功能，直接使用ai工具来编辑即可\\n\\n我的博客: https://blog.zbztb.cn/ \\n\\n![image-20251221113549057](assets/image-20251221113549057.png)\\n\\n\\n\\n## 重构了markdown图片处理脚本\\n\\n很多年前，因为要经常些markdown文章，但是如果markdown中的图片是存在本地的，有时候文章中删除了图片，但是文件没有被删除，自己本地一个一个找就比较麻烦，所以写了一个基于node的命令行工具\\n\\n> https://github.com/itcastWsy/rmmdimg\\n\\n![image-20251221113614582](assets/image-20251221113614582.png)\\n\\n## 将 Markdown 文件中的本地图片转换为网络地址\\n\\n一些技术博客，可以接受md文件中的网络图片，转成自己网站的图片，所以我可以把本地图片转换成网络图片后，就很方便发布文章了，这个工具只会保留自己图片30分钟，所以不能当成是永久图床来使用。\\n\\n> https://md.zbztb.cn/\\n\\n![image-20251221113836435](assets/image-20251221113836435.png)\\n\\n## 一个用于合并视频和字幕的命令行工具\\n\\n> https://gitcode.com/uksri/video-subtitle-merger\\n\\n一个用于合并视频和字幕的命令行工具，支持将字幕硬编码到视频中，确保在任何播放器中都能显示字幕。\\n\\n![image-20251221113919425](assets/image-20251221113919425.png)\\n\\n## 流碧卡片\\n\\n支持自定义背景色、文字颜色、字体、布局比例、圆角大小等细节参数。 高清导出 支持生成 2倍高清图片，完美适配微信、小红书、抖音等平台。 批量生成 支持长文本自动拆分，批量生成多张卡片并一键打包下载\\n\\n> https://card.zbztb.cn/\\n\\n![image-20251221114016973](assets/image-20251221114016973.png)\\n\\n## 词云工具\\n\\n纯前端免费的词云工具\\n\\n> https://wordsea.zbztb.cn/\\n\\n![image-20251221114100208](assets/image-20251221114100208.png)\\n\\n## 技术组织的官网\\n\\n我基于AI工具也开发了 青蓝逐码  技术组织的官网\\n\\n> https://www.qinglanzhuma.cn/\\n\\n![image-20251221114145829](assets/image-20251221114145829.png)\\n\\n## 还有很多鸿蒙的应用\\n\\n基于AI工具，还做了一些鸿蒙上架应用 如 可可图片编辑、青虫轻钢琴 等，都已经上架到了鸿蒙应用市场。\\n\\n## 最后\\n\\n目前重点使用的是iflow-cli + vscode。因为iflow 内置了很多主流的大模型，并且是个人免费，不用担心token，搭配vscode可以实现AI编程自由。\\n\\n\\n\\n## 联系我\\n\\n可以加我微信，带你了解更多互联网 HarmonyOS相关的资讯。\\n\\n![](https://wsy996.obs.cn-east-3.myhuaweicloud.com:443/%E5%BE%AE%E4%BF%A1%E5%8F%B7%E5%92%8C%E4%BA%8C%E7%BB%B4%E7%A0%81.jpg)"}'),c={name:"AI人工智能/2025 万少的AI编程之旅/2025 万少的AI编程之旅.md"};function m(g,t,u,b,k,_){return e(),n("div",null,[...t[0]||(t[0]=[d("",43)])])}const f=a(c,[["render",m]]);export{A as __pageData,f as default};
